grid = [[9]*20 for _ in range(10)]
markers = {0:[6],1:[17],2:[11],3:[7,15],4:[4,9],5:[3,11],6:[2,9],7:[10,11],8:[12,18],9:[]}
for r, cs in markers.items():
    for c in cs: grid[r][c]=1
out=[row[:] for row in grid]
for r, cs in markers.items():
    for a,b in zip(cs,cs[1:]):
        for c in range(a+1,b): out[r][c]=3
for c in range(20):
    rs=[r for r in range(10) if grid[r][c]==1]
    for a,b in zip(rs,rs[1:]):
        for r in range(a+1,b): out[r][c]=3
print(out)
print([len(r) for r in out])
